import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func hasMore() bool {
	skip()
	return pos < len(data)
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	nextInt() // n
	var tails []int64 // tails[i]: smallest tail of a strictly increasing run of length i+1
	count := 0
	for hasMore() {
		x := nextInt()
		count++
		i := sort.Search(len(tails), func(j int) bool { return tails[j] >= x })
		if i == len(tails) {
			tails = append(tails, x)
		} else {
			tails[i] = x
		}
	}
	fmt.Println(max(0, count-len(tails)-1))
}
